import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import * as core from '../src/core.js';
import { remapFixture, nestedFingerprintFixture } from './helpers/remap-fingerprint-fixture.js';

// These identities were captured from the exact released sources recorded in the
// fixture, not generated by the compatibility implementation under test. The two
// saved documents were authored/serialized by those original evaluators.
const eras = JSON.parse(
  fs.readFileSync(new URL('./fixtures/remap-fingerprint-eras.json', import.meta.url)),
);
const run = (doc) => core.evaluate(doc.layers[0], {}, doc.imageAssets, doc);
const point = (path, id) => path.contours.flatMap((c) => c.points).find((p) => p.id === id);
const plus = (a, b) => a.map((v, i) => v + b[i]);
const getRemap = (doc, id) => doc.layers[0].nodes.find((n) => n.id === id);
function author(f, fingerprint) {
  const input = run(f.doc).run(f.source.id),
    target = input.contours[0].points[0],
    edit = core.enableRemapPoint(f.remap, input, target.id);
  edit.fingerprint = fingerprint;
  edit.params.position.value = [3, 5];
  return { id: target.id, base: target.position, fingerprint };
}
function assertRetained(doc, remapId, saved, delta = [3, 5]) {
  const before = core.serialize(doc),
    evaluation = run(doc),
    path = evaluation.run(remapId);
  assert.equal(evaluation.error, null);
  assert.notEqual(path.remapSuspended, true, evaluation.warnings.join('\n'));
  assert.deepEqual(point(path, saved.id).position, plus(saved.base, delta));
  assert.equal(getRemap(doc, remapId).edits[0].fingerprint, saved.fingerprint);
  assert.equal(core.serialize(doc), before, 'evaluation must not mutate authored edits');
  return path;
}
function continueEditing(doc, remapId, saved) {
  const session = new core.CommandSession(doc),
    layerId = doc.layers[0].id,
    send = (type, payload = {}) =>
      session.dispatch({
        ...session.state,
        type,
        payload: { layerId, nodeId: remapId, ...payload },
      });
  assertRetained(session.snapshot(), remapId, saved);
  send('translate-points', { pointIds: [saved.id], delta: [2, -1] });
  assertRetained(session.snapshot(), remapId, saved, [5, 4]);
  send('set-parameter', { key: `remap.${saved.id}.position`, value: [6, 9] });
  const typed = core.serialize(session.snapshot());
  assertRetained(session.snapshot(), remapId, saved, [6, 9]);
  let token = send('begin-gesture', {
    target: { kind: 'remap-point', layerId, nodeId: remapId, pointId: saved.id, key: 'position' },
  });
  token = send('update-gesture', { ...token, update: { delta: [1, 2] } });
  assertRetained(session.previewSnapshot(token.gestureId).document, remapId, saved, [7, 11]);
  assert.equal(core.serialize(session.snapshot()), typed, 'drag preview stays private');
  send('commit-gesture', token);
  const dragged = core.serialize(session.snapshot());
  assertRetained(session.snapshot(), remapId, saved, [7, 11]);
  send('undo');
  assert.equal(core.serialize(session.snapshot()), typed);
  send('redo');
  assert.equal(core.serialize(session.snapshot()), dragged);
  let reopened = session.snapshot();
  for (let i = 0; i < 2; i++) {
    reopened = core.deserialize(core.serialize(reopened));
    assertRetained(reopened, remapId, saved, [7, 11]);
  }
}

for (const era of ['historical', 'current']) {
  test(`original ${era}-authored saved JSON reopens and remains editable without rebinding`, () => {
    const doc = core.deserialize(
      fs.readFileSync(new URL(`./fixtures/remap-saved-${era}.json`, import.meta.url), 'utf8'),
    );
    const remap = getRemap(doc, 'saved-remap'),
      saved = {
        id: remap.edits[0].pointId,
        base: [16, 16],
        fingerprint: remap.edits[0].fingerprint,
      };
    assertRetained(doc, remap.id, saved);
    continueEditing(doc, remap.id, saved);
  });
}
for (const record of eras.records) {
  const { type, input, route } = record;
  test(`${type}/${input}/${route}: exact era identities, cold/cache reopen, nudge, typed edit, drag, undo and reload`, () => {
    for (const era of ['historical', 'current'].filter((era) => record[era])) {
      const f = remapFixture(core, type, input, route),
        evaluation = run(f.doc),
        source = evaluation.run(f.source.id);
      if (record.historical) assert.equal(source.fingerprint, record.historical);
      assert.equal(core.remapFingerprintMatches(source, record.current), true);
      // No metadata is serialized or entrusted to arbitrary cloned inputs.
      assert.equal(
        Object.keys(source).some((key) => /alias|compatib/i.test(key)),
        false,
      );
      if (record.current !== source.fingerprint)
        assert.equal(core.remapFingerprintMatches(structuredClone(source), record.current), false);
      const cached = run(f.doc);
      assert.ok(cached.stats.reused > 0);
      assert.equal(core.remapFingerprintMatches(cached.run(f.source.id), record.current), true);
      const saved = author(f, record[era]),
        json = core.serialize(f.doc),
        reopened = core.deserialize(json);
      assertRetained(reopened, f.remap.id, saved);
      continueEditing(reopened, f.remap.id, saved);
    }
  });
}

test('mixed-era edits and chained Remaps retain their original hashes through batch editing and reload', () => {
  const record = eras.records[0],
    f = remapFixture(core),
    input = run(f.doc).run(f.source.id),
    targets = input.contours[0].points.slice(0, 2),
    second = core.node('Path Remap');
  second.id = 'compat-second-remap';
  second.params.path.source = f.remap.id;
  f.layer.nodes.push(second);
  f.layer.nodes.find((n) => n.id === 'compat-paint').params.path.source = second.id;
  for (const [i, target] of targets.entries()) {
    const edit = core.enableRemapPoint(f.remap, input, target.id);
    edit.fingerprint = record[i ? 'current' : 'historical'];
    edit.params.position.value = [3, 5];
  }
  const downstream = run(f.doc).run(f.remap.id),
    edit = core.enableRemapPoint(second, downstream, targets[0].id);
  edit.fingerprint = record.current;
  edit.params.position.value = [-2, 1];
  let loaded = core.deserialize(core.serialize(f.doc));
  for (let i = 0; i < 2; i++) {
    const evaluation = run(loaded),
      path = evaluation.run(second.id);
    assert.equal(evaluation.warnings.length, 0);
    assert.deepEqual(
      point(path, targets[0].id).position,
      plus(targets[0].position, [1 + i, 6 + i]),
    );
    assert.deepEqual(
      point(path, targets[1].id).position,
      plus(targets[1].position, [3 + i, 5 + i]),
    );
    const live = getRemap(loaded, f.remap.id);
    assert.deepEqual(
      live.edits.map((e) => e.fingerprint),
      [record.historical, record.current],
    );
    core.translateRemapPoints(
      live,
      evaluation.run(f.source.id),
      targets.map((p) => p.id),
      [1, 1],
    );
    loaded = core.deserialize(core.serialize(loaded));
  }
});

const changes = {
  pitch: (f) => (f.effect.params.pitch.value = 9),
  origin: (f) => (f.effect.params.gridOrigin.value = [1, 0]),
  tone: (f) => (f.effect.params.tonePower.value = 2),
  dots: (f) => {
    f.effect.operation = 'square';
    f.effect.params.dotSize.value = 4;
  },
  'equal-geometry source rewiring': (f) => {
    const replacement = structuredClone(f.fill);
    replacement.id = 'replacement-fill';
    f.layer.nodes.push(replacement);
    f.effect.params.path.source = replacement.id;
  },
  'equal-geometry transitive rewiring': (f) => {
    const replacement = structuredClone(f.shape);
    replacement.id = 'replacement-shape';
    f.layer.nodes.push(replacement);
    f.fill.params.path.source = replacement.id;
  },
};
for (const [name, change] of Object.entries(changes))
  test(`${name} suspends both eras and rejects nudge/drag atomically`, () => {
    const record = eras.records[0];
    for (const era of ['historical', 'current']) {
      const f = remapFixture(core),
        saved = author(f, record[era]),
        beforeGeometry = run(f.doc).run(f.source.id).contours;
      change(f);
      const evaluation = run(f.doc),
        input = evaluation.run(f.source.id),
        path = evaluation.run(f.remap.id);
      if (name.includes('equal-geometry')) assert.deepEqual(input.contours, beforeGeometry);
      assert.equal(path.remapSuspended, true);
      assert.equal(core.remapFingerprintMatches(input, saved.fingerprint), false);
      const session = new core.CommandSession(f.doc),
        before = core.serialize(session.snapshot()),
        send = (type, payload = {}) =>
          session.dispatch({
            ...session.state,
            type,
            payload: { layerId: f.layer.id, nodeId: f.remap.id, ...payload },
          });
      assert.throws(
        () => send('translate-points', { pointIds: [saved.id], delta: [1, 2] }),
        /suspended/,
      );
      assert.equal(core.serialize(session.snapshot()), before);
      assert.throws(
        () =>
          send('begin-gesture', {
            target: {
              kind: 'remap-point',
              layerId: f.layer.id,
              nodeId: f.remap.id,
              pointId: saved.id,
              key: 'position',
            },
          }),
        /suspended/,
      );
      assert.equal(core.serialize(session.snapshot()), before);
      assert.equal(session.historyView.past.length, 0);
      assert.equal(
        getRemap(session.snapshot(), f.remap.id).edits[0].fingerprint,
        saved.fingerprint,
      );
    }
  });

test('expression-reference rewiring with equal values and changed values still suspends', () => {
  const record = eras.records.find((r) => r.route === 'expression');
  for (const change of ['reference', 'value']) {
    const f = remapFixture(core, 'Halftone', 'vector', 'expression'),
      saved = author(f, record.current),
      original = run(f.doc).run(f.source.id).contours,
      value = f.layer.nodes.find((n) => n.id === 'compat-expression-source');
    if (change === 'reference') {
      const replacement = structuredClone(value);
      replacement.id = 'replacement-expression-source';
      f.layer.nodes.push(replacement);
      f.effect.params.pitch.expression = core.parameterReferenceExpression(replacement.id, 'value');
    } else value.params.value.value = 9;
    const evaluation = run(f.doc),
      source = evaluation.run(f.source.id);
    if (change === 'reference') assert.deepEqual(source.contours, original);
    assert.equal(core.remapFingerprintMatches(source, saved.fingerprint), false);
    assert.equal(evaluation.run(f.remap.id).remapSuspended, true);
  }
});

test('missing points, arbitrary fingerprints and caller-provided alias properties never rebind', () => {
  const f = remapFixture(core),
    record = eras.records[0],
    saved = author(f, record.current),
    input = run(f.doc).run(f.source.id);
  for (const fake of ['sha256:' + '0'.repeat(64), record.current + 'x', undefined]) {
    input.compatibleFingerprints = [fake];
    input.fingerprintAliases = [fake];
    assert.equal(core.remapFingerprintMatches(input, fake), false);
    f.remap.edits[0].fingerprint = fake;
    assert.equal(run(f.doc).run(f.remap.id).remapSuspended, true);
  }
  f.remap.edits[0].fingerprint = saved.fingerprint;
  f.remap.edits[0].pointId = 'missing-point';
  assert.equal(run(f.doc).run(f.remap.id).remapSuspended, true);
});

test('nested Composition appearance retains exact current-era hashes across clone/cache/reload', () => {
  for (const record of eras.nested) {
    let { doc } = nestedFingerprintFixture(core, record.expression);
    for (let repetition = 0; repetition < 3; repetition++) {
      for (const [index, identities] of record.layers.entries()) {
        const evaluation = core.evaluate(doc.layers[index], {}, {}, doc);
        assert.equal(evaluation.error, null);
        for (const [id, identity] of Object.entries(identities))
          assert.equal(core.remapFingerprintMatches(evaluation.run(id), identity), true, id);
      }
    }
    doc = core.deserialize(core.serialize(doc));
    for (const [index, identities] of record.layers.entries()) {
      const evaluation = core.evaluate(doc.layers[index], {}, {}, doc);
      assert.equal(evaluation.error, null);
      for (const [id, identity] of Object.entries(identities))
        assert.equal(core.remapFingerprintMatches(evaluation.run(id), identity), true, id);
    }
  }
});

test('all five vector/image families reject real controls and equal-geometry source swaps in both eras', () => {
  for (const record of eras.records.filter((r) => r.route === 'convert' && r.historical))
    for (const era of ['historical', 'current'])
      for (const change of ['pitch', 'origin', 'tone', 'source']) {
        const f = remapFixture(
            core,
            record.type,
            record.input,
            change === 'tone' ? 'tone-control' : 'convert',
          ),
          saved = author(
            f,
            (change === 'tone'
              ? eras.toneControls.find((r) => r.type === record.type && r.input === record.input)
              : record)[era],
          ),
          before = run(f.doc).run(f.source.id).contours;
        if (change === 'pitch') f.effect.params.pitch.value = 9;
        if (change === 'origin') f.effect.params.gridOrigin.value = [1, 0];
        if (change === 'tone') f.effect.params.tonePower.value = 2;
        if (change === 'source') {
          const original = record.input === 'image' ? f.shape : f.fill,
            replacement = structuredClone(original);
          replacement.id = 'equal-geometry-replacement';
          f.layer.nodes.push(replacement);
          f.effect.params.path.source = replacement.id;
        }
        const evaluation = run(f.doc),
          source = evaluation.run(f.source.id),
          label = `${record.type}/${record.input}/${era}/${change}`;
        assert.equal(evaluation.error, null, label);
        if (change === 'source') assert.deepEqual(source.contours, before, label);
        if (change === 'tone') assert.notDeepEqual(source.contours, before, label);
        assert.equal(core.remapFingerprintMatches(source, saved.fingerprint), false, label);
        assert.equal(evaluation.run(f.remap.id).remapSuspended, true, label);
        assert.equal(f.remap.edits[0].fingerprint, saved.fingerprint, label);
      }
});

for (const era of ['historical', 'current'])
  test(`original ${era} saved literal-expression edit retains its identity and remains editable`, () => {
    const doc = core.deserialize(
        fs.readFileSync(
          new URL(`./fixtures/remap-saved-literal-${era}.json`, import.meta.url),
          'utf8',
        ),
      ),
      remap = getRemap(doc, 'compat-remap'),
      input = run(doc).run(remap.params.path.source),
      saved = {
        id: remap.edits[0].pointId,
        base: point(input, remap.edits[0].pointId).position,
        fingerprint: remap.edits[0].fingerprint,
      };
    assertRetained(doc, remap.id, saved);
    continueEditing(doc, remap.id, saved);
    const value = core.node('Value');
    value.id = 'introduced-reference';
    value.params.value.value = 8;
    doc.layers[0].nodes.push(value);
    const effect = doc.layers[0].nodes.find((n) => n.id === 'compat-effect');
    effect.params.pitch.expression = core.parameterReferenceExpression(value.id, 'value');
    const evaluation = run(doc),
      source = evaluation.run(remap.params.path.source);
    assert.deepEqual(source.contours, input.contours);
    assert.equal(core.remapFingerprintMatches(source, saved.fingerprint), false);
    assert.equal(evaluation.run(remap.id).remapSuspended, true);
  });

test('reference-free grammar has no hidden dynamic dependency; authored base values still invalidate', () => {
  for (const text of ['time', 'frame', 'random()', 'Date.now()', 'process', 'fetch(1)'])
    assert.throws(() => core.expression(text), undefined, text);
  for (const kind of ['scalar-base', 'vector-base', 'color-base']) {
    const f = remapFixture(core);
    if (kind === 'scalar-base') f.effect.params.pitch.expression = 'value';
    if (kind === 'vector-base') f.shape.params.center.expression = 'value; value';
    if (kind === 'color-base') {
      f.doc.schemaVersion = 42;
      f.fill.params.color.value = null;
      f.fill.params.color.expression = 'value';
      f.layer.fill = '#000000';
    }
    const input = run(f.doc).run(f.source.id),
      id = input.contours[0].points[0].id;
    core.enableRemapPoint(f.remap, input, id).params.position.value = [3, 5];
    if (kind === 'scalar-base') f.effect.params.pitch.value = 9;
    if (kind === 'vector-base') f.shape.params.center.value = [9, 8];
    if (kind === 'color-base') f.layer.fill = '#ff0000';
    const evaluation = run(f.doc);
    assert.equal(evaluation.error, null, kind);
    assert.equal(evaluation.run(f.remap.id).remapSuspended, true, kind);
  }
});

test('dual identities do not repeat geometry evaluation or effective parameter reads', () => {
  const f = remapFixture(core),
    record = eras.records[0],
    reads = { shape: 0, pitch: 0 };
  for (const [name, parameter] of [
    ['shape', f.shape.params.size],
    ['pitch', f.effect.params.pitch],
  ]) {
    const value = parameter.value;
    Object.defineProperty(parameter, 'value', {
      enumerable: true,
      get() {
        reads[name]++;
        return value;
      },
    });
  }
  const evaluation = run(f.doc),
    input = evaluation.run(f.source.id);
  assert.equal(evaluation.error, null);
  // One cache-key read and one effective-value read per parameter, just as for
  // the original single-identity evaluator. Hash recipes reuse resolved values.
  assert.deepEqual(reads, { shape: 2, pitch: 2 });
  assert.equal(evaluation.stats.computed, 7);
  assert.equal(core.remapFingerprintMatches(input, record.current), true);
  assert.deepEqual(reads, { shape: 2, pitch: 2 });
});
